//-------------------------------------------------------------------------------------------------
yaget::render::placeholders::Texture yaget::render::placeholders::GetTextureData()
{
        //int mSizeX = 0;
        //int mSizeY = 0;
        //int mComponents = 0;    // number of components in image (rgba = 4, Single = 1)

    Texture texture;
    texture.mSizeX = placeholder_image.width;
    texture.mSizeY = placeholder_image.height;
    texture.mComponents = placeholder_image.bytes_per_pixel;
    texture.mPixels = { placeholder_image.pixel_data, texture.mSizeX * texture.mSizeY * texture.mComponents };

    return texture;
}